package com.jobproof.modules.aigateway.security;
import java.nio.*; import java.nio.charset.*; import java.security.*; import java.util.*; import javax.crypto.*; import javax.crypto.spec.*;
public final class ApiKeyCipher {
 private static final byte FORMAT=1; private static final int NONCE_BYTES=12; private static final byte[] AAD="jobproof:aigateway:api-key:v1".getBytes(StandardCharsets.UTF_8); private final SecretKeySpec key; private final SecureRandom random;
 public ApiKeyCipher(String encoded){this(encoded,new SecureRandom());}
 ApiKeyCipher(String encoded,SecureRandom random){if(encoded==null || encoded.isBlank())throw new IllegalStateException("JOBPROOF_AI_MASTER_KEY is required");byte[] raw;try{raw=Base64.getDecoder().decode(encoded);}catch(IllegalArgumentException e){throw new IllegalStateException("AI master key must be Base64",e);}if(raw.length!=32)throw new IllegalStateException("AI master key must decode to 32 bytes");key=new SecretKeySpec(raw,"AES");this.random=random;}
 public String encrypt(String value){if(value==null || value.isBlank())throw new IllegalArgumentException("API key is required");byte[] nonce=new byte[NONCE_BYTES];random.nextBytes(nonce);try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,nonce));c.updateAAD(AAD);byte[] encrypted=c.doFinal(value.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(ByteBuffer.allocate(1+nonce.length+encrypted.length).put(FORMAT).put(nonce).put(encrypted).array());}catch(GeneralSecurityException e){throw new IllegalStateException("Unable to encrypt API key",e);}}
 public String decrypt(String encoded){try{byte[] p=Base64.getDecoder().decode(encoded);if(p.length<=1+NONCE_BYTES || p[0]!=FORMAT)throw new IllegalArgumentException("Unsupported encrypted API key format");byte[] nonce=Arrays.copyOfRange(p,1,1+NONCE_BYTES),data=Arrays.copyOfRange(p,1+NONCE_BYTES,p.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,nonce));c.updateAAD(AAD);return new String(c.doFinal(data),StandardCharsets.UTF_8);}catch(GeneralSecurityException|IllegalArgumentException e){throw new IllegalArgumentException("Encrypted API key is invalid or was tampered with",e);}}
}